mapper.select:
SELECT a.id, a.resume_id, a.job_id, a.user_id, a.status, a.match_score, a.company_remark, a.delivery_time, a.handle_time, a.deleted FROM application a JOIN job j ON j.id = a.job_id JOIN resume r ON r.id = a.resume_id WHERE j.company_id = #{companyId} AND a.deleted = 0 AND a.job_id = #{jobId} AND a.status = #{status}
AND (r.name LIKE CONCAT('%', #{keyword}, '%') OR r.skill_tags LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY a.delivery_time DESC

mapper.update:
UPDATE application
SET status = #{status}, company_remark = #{remark}, handle_time = #{handleTime}
WHERE id = #{id} AND deleted = 0
